// examples/stdlib/reward.ax — composable metrics for ASI score functions.
//
// Every adaptive demo hand-codes a score expression like:
//   let s = accuracy * 0.7 - 0.1 * tokens + (passes_redteam as i64) * 30
// That works but bakes the metric into the optimization loop, making it
// hard to swap, weight, or compose without rewriting the @[adaptive] fn.
//
// This module gives a tiny algebra of named, weight-able metrics that
// compose without changing the optimizer surface. The score is still an
// f64 (what `goal_run` / `@[adaptive]` understand); we add structure
// around it so a multi-objective demo doesn't degenerate to a magic
// arithmetic expression buried inside the scoring fn.
//
//   axon test examples/stdlib/reward.ax  → 8 tests pass

// A scalar metric with a known upper bound. `max` is the value at which
// the metric is "fully satisfied"; the optimizer should drive `score`
// toward `max`. Keeping the bound explicit lets combinators normalize
// across metrics that live on different scales (a 0..100 accuracy score
// and a 0..1 confidence score should mix as equals, not as 100:1).
type Reward = { name: str, score: f64, max: f64 }

fn reward_new(name: str, score: f64, max: f64) -> Reward {
    Reward { name: name, score: score, max: max }
}

// Normalize to [0, 1]. `max = 0` is treated as "no reward" rather than
// dividing by zero — a degenerate case callers can branch on.
fn reward_unit(r: Reward) -> f64 {
    if r.max == 0.0 { 0.0 }
    else { r.score / r.max }
}

// Weighted sum: combine two rewards into a single normalized score in
// `[0, weight_a + weight_b]`. The weights stay in user space (not
// baked into the metric) so the same Reward can participate in
// multiple compositions.
fn reward_blend(a: Reward, weight_a: f64, b: Reward, weight_b: f64) -> f64 {
    weight_a * reward_unit(a) + weight_b * reward_unit(b)
}

// Scale a reward — useful when one metric needs to count more without
// rewriting its underlying score. Returns a fresh Reward.
fn reward_scale(r: Reward, factor: f64) -> Reward {
    Reward { name: r.name, score: r.score * factor, max: r.max * factor }
}

// Penalize: subtract a fraction of a "cost" reward from a "value"
// reward in normalized space. `cost_weight` is the discount factor
// (0.1 means "10% off the value for every unit of cost"). Returns the
// combined normalized score; negative if cost dominates.
fn reward_penalize(value: Reward, cost: Reward, cost_weight: f64) -> f64 {
    reward_unit(value) - cost_weight * reward_unit(cost)
}

// Take the minimum of two rewards — "agent must do well on BOTH axes".
// Returns the normalized score of the weaker dim, so the optimizer is
// forced to lift the laggard.
fn reward_min(a: Reward, b: Reward) -> f64 {
    let ua = reward_unit(a)
    let ub = reward_unit(b)
    if ua < ub { ua } else { ub }
}

// Take the max — "any axis is fine".
fn reward_max(a: Reward, b: Reward) -> f64 {
    let ua = reward_unit(a)
    let ub = reward_unit(b)
    if ua > ub { ua } else { ub }
}

// ── Tests ────────────────────────────────────────────────────────────────────
// `assert_eq_f64` does exact equality; for everything that isn't bit-exact we
// fall back to an abs-difference check with `assert` so the tolerance is
// explicit in the test.

fn approx(a: f64, b: f64, eps: f64) -> bool {
    let d = a - b
    let abs_d = if d < 0.0 { -d } else { d }
    abs_d < eps
}

@[test]
fn test_unit_zero_max() {
    let r = reward_new("empty", 0.0, 0.0)
    assert_eq_f64(reward_unit(r), 0.0)
}

@[test]
fn test_unit_normal() {
    let r = reward_new("acc", 75.0, 100.0)
    assert_eq_f64(reward_unit(r), 0.75)
}

@[test]
fn test_unit_at_max() {
    let r = reward_new("perfect", 100.0, 100.0)
    assert_eq_f64(reward_unit(r), 1.0)
}

@[test]
fn test_blend_equal_weights() {
    let a = reward_new("a", 80.0, 100.0)    // unit = 0.8
    let b = reward_new("b", 0.5, 1.0)       // unit = 0.5
    // 0.5 * 0.8 + 0.5 * 0.5 = 0.65
    assert(approx(reward_blend(a, 0.5, b, 0.5), 0.65, 0.0001))
}

@[test]
fn test_scale_preserves_unit_value() {
    let r = reward_new("x", 75.0, 100.0)
    let r2 = reward_scale(r, 3.0)
    // score and max both triple → unit stays 0.75
    assert(approx(reward_unit(r2), 0.75, 0.0001))
}

@[test]
fn test_penalize_subtracts_cost() {
    let value = reward_new("v", 100.0, 100.0)  // unit = 1.0
    let cost  = reward_new("c", 5.0, 10.0)     // unit = 0.5
    // 1.0 - 0.1 * 0.5 = 0.95
    assert(approx(reward_penalize(value, cost, 0.1), 0.95, 0.0001))
}

@[test]
fn test_min_returns_weaker_dim() {
    let a = reward_new("strong", 90.0, 100.0) // 0.9
    let b = reward_new("weak",   30.0, 100.0) // 0.3
    assert(approx(reward_min(a, b), 0.3, 0.0001))
}

@[test]
fn test_max_returns_stronger_dim() {
    let a = reward_new("strong", 90.0, 100.0) // 0.9
    let b = reward_new("weak",   30.0, 100.0) // 0.3
    assert(approx(reward_max(a, b), 0.9, 0.0001))
}

sources.examples/stdlib/principal_mint.ax:
// Tier-1 stdlib: Principal minting with attenuation — the capability_minter TCB
// component at the USERLAND layer. Realizes ROADMAP §6 row 7 ("A Principal can
// mint a sub-Principal with a strict subset of capabilities + budget") and the
// hard half of invariant I-12 ("self-modification cannot weaken the TCB — may
// never grant itself a capability it didn't already hold").
//
// The safety property is ATTENUATION, enforced BY CONSTRUCTION in `mint`:
//   • each child cap = (want_X && parent.X) — a child can hold C only if the
//     parent holds C; escalation is unrepresentable, not merely rejected.
//   • the child's budget is CARVED from the parent's remaining budget: the grant
//     is clamped to what the parent has left, debited from the parent, and the
//     child can never spend past it. The sum of live budgets stays bounded by
//     the root cap — minting cannot manufacture authority.
//
// Self-contained: Budget is inlined from budget.ax (same move as goal.ax).
//
//   axon test examples/stdlib/principal_mint.ax   # run the @[test]s
//   axon run  examples/stdlib/principal_mint.ax   # demo

// ── Budget (inlined from budget.ax) ──────────────────────────────────────────
type Budget = { used: i64, cap: i64 }

fn budget_new(cap: i64) -> Budget { Budget { used: 0, cap: cap } }
fn budget_spend(b: Budget, amount: i64) -> Budget { Budget { used: b.used + amount, cap: b.cap } }
fn budget_remaining(b: Budget) -> i64 { let r = b.cap - b.used  if r < 0 { 0 } else { r } }
fn budget_exhausted(b: Budget) -> bool { b.used >= b.cap }

// ── Principal ────────────────────────────────────────────────────────────────
// Capabilities (net/fs_write/exec) and a budget travel together. `parent` is the
// name of the minting principal ("-" for a root), kept for audit lineage.
type Principal = {
    name: str,
    parent: str,
    net: bool,
    fs_write: bool,
    exec: bool,
    budget: Budget,
}

// A root Principal: the originating authority. Holds exactly the caps it is given
// and the full budget. Everything below it can only attenuate from here.
fn root(name: str, net: bool, fs_write: bool, exec: bool, budget_cap: i64) -> Principal {
    Principal {
        name: name, parent: "-",
        net: net, fs_write: fs_write, exec: exec,
        budget: budget_new(budget_cap),
    }
}

// ── Accessors / predicates ───────────────────────────────────────────────────
fn p_budget_remaining(p: Principal) -> i64 { budget_remaining(p.budget) }

// Does `p` hold the named capability? Unknown names answer false (deny by default).
fn holds(p: Principal, cap: str) -> bool {
    if str_eq(cap, "net") { p.net }
    else if str_eq(cap, "fs_write") { p.fs_write }
    else if str_eq(cap, "exec") { p.exec }
    else { false }
}

// Whether `p` could mint a child wanting these caps + this budget at all — i.e.
// it holds every requested cap and has at least 1 unit of budget left to carve.
// (mint() is total and still safe without this; can_mint is the explicit gate.)
fn can_mint(p: Principal, want_net: bool, want_fs_write: bool, want_exec: bool, budget_grant: i64) -> bool {
    let caps_ok = (!want_net || p.net) && (!want_fs_write || p.fs_write) && (!want_exec || p.exec)
    let budget_ok = budget_grant > 0 && p_budget_remaining(p) > 0
    caps_ok && budget_ok
}

// ── MINT — the attenuating constructor ───────────────────────────────────────
// Returns (updated_parent_with_debited_budget, child). ATTENUATION is enforced
// here by construction:
//   • child cap_X = want_X && parent.X      → never more than the parent holds
//   • grant      = clamp(budget_grant, 0, parent_remaining)  → never over-grant
//   • parent.budget.used += grant            → the grant is carved, not conjured
fn mint(
    parent: Principal,
    child_name: str,
    want_net: bool,
    want_fs_write: bool,
    want_exec: bool,
    budget_grant: i64,
) -> (Principal, Principal) {
    let c_net = want_net && parent.net
    let c_fs = want_fs_write && parent.fs_write
    let c_exec = want_exec && parent.exec
    let grant = min_i64(max_i64(budget_grant, 0), p_budget_remaining(parent))
    let new_parent = Principal {
        name: parent.name, parent: parent.parent,
        net: parent.net, fs_write: parent.fs_write, exec: parent.exec,
        budget: budget_spend(parent.budget, grant),
    }
    let child = Principal {
        name: child_name, parent: parent.name,
        net: c_net, fs_write: c_fs, exec: c_exec,
        budget: budget_new(grant),
    }
    (new_parent, child)
}

// ── Spend on a Principal ─────────────────────────────────────────────────────
// Debit `amount` from the principal's own budget, returning the updated principal.
// Caps are untouched; only its carved budget can be consumed.
fn p_spend(p: Principal, amount: i64) -> Principal {
    Principal {
        name: p.name, parent: p.parent,
        net: p.net, fs_write: p.fs_write, exec: p.exec,
        budget: budget_spend(p.budget, amount),
    }
}

// ── Authorization gate ───────────────────────────────────────────────────────
// An action declaring which caps it needs is authorized only if `p` holds every
// one of them AND still has budget headroom. Mirrors agent.ax `authorized`.
fn authorize(p: Principal, needs_net: bool, needs_fs_write: bool, needs_exec: bool) -> bool {
    let caps = (!needs_net || p.net) && (!needs_fs_write || p.fs_write) && (!needs_exec || p.exec)
    caps && !budget_exhausted(p.budget)
}

// ── Tests ────────────────────────────────────────────────────────────────────
@[test]
fn test_mint_subset_works() {
    // A full-cap root mints a child asking for a strict subset; the child gets
    // exactly the subset and a carved budget.
    let r = root("root", true, true, true, 100)
    let (_r2, c) = mint(r, "child", true, false, true, 40)
    assert(c.net)
    assert(!c.fs_write)
    assert(c.exec)
    assert_eq(c.budget.cap, 40)
    assert_eq_str(c.parent, "root")
}

@[test]
fn test_mint_cannot_escalate_caps() {
    // Parent lacks net. Child requests net → child does NOT get net. Escalation
    // is impossible by construction (want_net && parent.net == false).
    let r = root("root", false, true, false, 100)
    let (_r2, c) = mint(r, "child", true, true, true, 30)
    assert(!c.net)        // requested but denied — parent had no net
    assert(c.fs_write)    // requested and parent held it
    assert(!c.exec)       // requested but denied — parent had no exec
    assert(!holds(c, "net"))
}

@[test]
fn test_budget_is_carved_from_parent() {
    // The grant is debited from the parent and capped in the child; the two
    // live budgets sum to no more than the original (carve, not conjure).
    let r = root("root", true, false, false, 100)
    let (r2, c) = mint(r, "child", true, false, false, 40)
    assert_eq(p_budget_remaining(r2), 60)   // parent debited by exactly 40
    assert_eq(c.budget.cap, 40)             // child capped at the grant
    assert_eq(c.budget.used, 0)
    // child can spend up to the grant but no further
    let c2 = p_spend(c, 40)
    assert(budget_exhausted(c2.budget))
    assert_eq(budget_remaining(c2.budget), 0)
    // remaining child budget + remaining parent budget <= original root cap
    assert(budget_remaining(c.budget) + p_budget_remaining(r2) <= 100)
}

@[test]
fn test_overgrant_is_clamped_to_parent_remaining() {
    // Root with only 50 left is asked to grant 200 → clamped to 50; parent
    // drops to 0, child capped at 50. Authority cannot be manufactured.
    let r = root("root", true, true, true, 50)
    let (r2, c) = mint(r, "greedy", true, true, true, 200)
    assert_eq(c.budget.cap, 50)
    assert_eq(p_budget_remaining(r2), 0)
}

@[test]
fn test_chain_stays_attenuated() {
    // root(net,fs,exec) → child(net,fs) → grandchild(net). At each hop a cap can
    // only be dropped, never regained: grandchild ⊆ child ⊆ root. The grandchild
    // re-requesting exec/fs gets neither, because the middle child never held them.
    let r = root("root", true, true, true, 100)
    let (_r2, c) = mint(r, "child", true, true, false, 60)
    assert(c.net && c.fs_write && !c.exec)
    let (_c2, g) = mint(c, "grand", true, true, true, 30)
    assert(g.net)        // child had net
    assert(g.fs_write)   // child had fs
    assert(!g.exec)      // child never had exec → grandchild can't get it
    assert_eq(g.budget.cap, 30)   // budget attenuates too
}

@[test]
fn test_no_cap_root_mints_only_no_cap_children() {
    // A sandboxed root holds nothing; every child it mints — whatever it asks —
    // holds nothing. The floor is sealed.
    let r = root("sandbox", false, false, false, 100)
    let (_r2, c) = mint(r, "child", true, true, true, 50)
    assert(!c.net)
    assert(!c.fs_write)
    assert(!c.exec)
    assert(!holds(c, "net") && !holds(c, "fs_write") && !holds(c, "exec"))
}

@[test]
fn test_can_mint_gate() {
    // can_mint reflects whether mint would actually grant anything: true when the
    // parent holds the requested caps and has budget, false when it lacks a cap.
    let r = root("root", true, false, false, 100)
    assert(can_mint(r, true, false, false, 10))    // wants net, has net, has budget
    assert(!can_mint(r, true, true, false, 10))    // wants fs_write, lacks it
    let drained = p_spend(r, 100)
    assert(!can_mint(drained, true, false, false, 10))  // no budget left
}

@[test]
fn test_authorize_requires_caps_and_budget() {
    // The action gate: needs net → must hold net AND not be budget-exhausted.
    let r = root("root", true, false, false, 100)
    assert(authorize(r, true, false, false))     // has net, has budget
    assert(!authorize(r, false, true, false))    // needs fs_write, lacks it
    let drained = p_spend(r, 100)
    assert(!authorize(drained, true, false, false))  // budget exhausted → denied
}

fn main() {
    // Demo: a full-authority root delegates a strict subset to a worker, which
    // re-delegates a still-smaller subset to a sub-task. Authority only shrinks.
    let r = root("orchestrator", true, true, true, 1000)
    let (r2, worker) = mint(r, "fetch-worker", true, false, false, 300)
    let wn = to_str(worker.net)
    let wf = to_str(worker.fs_write)
    let we = to_str(worker.exec)
    let wb = to_str(worker.budget.cap)
    println("worker caps: net={wn} fs={wf} exec={we}, budget={wb}")
    let rem = to_str(p_budget_remaining(r2))
    println("orchestrator budget left: {rem}")
    let (_w2, sub) = mint(worker, "fetch-sub", true, true, true, 500)
    let sn = to_str(sub.net)
    let sf = to_str(sub.fs_write)
    let se = to_str(sub.exec)
    let sb = to_str(sub.budget.cap)
    println("sub caps: net={sn} fs={sf} exec={se} (fs/exec denied — worker never held them)")
    println("sub budget: {sb} (clamped to worker's 300)")
}

sources.examples/stdlib/trace.ax:
// Tier-1 stdlib: Trace — a replayable execution record.
//
// ROADMAP §6 Tier-1 type `Trace` ("replayable execution record"). A Trace is the
// VALUE-level counterpart to the runtime provenance log (`axon trace` reads the
// JSONL the engine writes): a record of the steps an autonomous run took, that
// you can REPLAY and check for DIVERGENCE. The whole point of a replayable trace
// is determinism auditing — replaying a recorded run must reproduce it; a replay
// that DIVERGES is a non-determinism bug (an unseeded RNG, a wall-clock read, a
// live network call that crept into a path that should be pure). The replay
// engine's job is to catch exactly that.
//
// Modeled with two parallel `[i64]` arrays (action tag + result per step) since
// this is pre-tuple-array userland. A step is `(action, result)`: `action` is an
// opaque op tag (which tool/branch ran), `result` the i64 outcome it produced.
//
//   axon test examples/stdlib/trace.ax
//   axon run  examples/stdlib/trace.ax

type Trace = {
    actions: [i64],   // the op tag at each step (what ran)
    results: [i64],   // the outcome each op produced
}

fn trace_new() -> Trace {
    Trace { actions: [], results: [] }
}

// Append one recorded step. Immutable: returns a new Trace.
fn trace_record(t: Trace, action: i64, result: i64) -> Trace {
    Trace {
        actions: arr_push(&t.actions, action),
        results: arr_push(&t.results, result),
    }
}

// Number of recorded steps.
fn trace_len(t: Trace) -> i64 {
    len(t.actions)
}

// The result recorded at step `i`, or -1 if out of range.
fn trace_result_at(t: Trace, i: i64) -> i64 {
    if i < 0 { 0 - 1 } else { if i >= len(t.results) { 0 - 1 } else { t.results[i] } }
}

// Two traces are EQUIVALENT iff they recorded the same actions in the same order
// AND each produced the same result — i.e. a replay reproduced the original. A
// difference in length, action order, or any result means DIVERGENCE.
fn trace_equiv(a: Trace, b: Trace) -> bool {
    if len(a.actions) != len(b.actions) {
        false
    } else {
        let n = len(a.actions)
        let i = 0
        let ok = true
        while i < n {
            let same_act = a.actions[i] == b.actions[i]
            let same_res = a.results[i] == b.results[i]
            if same_act && same_res { ok = ok } else { ok = false }
            i = i + 1
        }
        ok
    }
}

// The index of the FIRST diverging step between a recorded trace and its replay,
// or -1 when they are equivalent. This is what a replay engine reports: "the runs
// agreed up to step k, then diverged" — the bisection point for the
// non-determinism bug. A length difference past the shorter trace counts as
// divergence at the first missing step.
fn trace_divergence(a: Trace, b: Trace) -> i64 {
    let n = min_i64(len(a.actions), len(b.actions))
    let i = 0
    let found = 0 - 1
    while i < n {
        let same_act = a.actions[i] == b.actions[i]
        let same_res = a.results[i] == b.results[i]
        if same_act && same_res {
            i = i + 1
        } else {
            found = i
            i = n
        }
    }
    // Equal on the common prefix but different lengths → diverges at the prefix end.
    if found < 0 {
        if len(a.actions) == len(b.actions) { 0 - 1 } else { n }
    } else {
        found
    }
}

@[test]
fn test_trace_records_steps() {
    let t = trace_record(trace_record(trace_new(), 1, 100), 2, 200)
    assert_eq(trace_len(t), 2)
    assert_eq(trace_result_at(t, 0), 100)
    assert_eq(trace_result_at(t, 1), 200)
    assert_eq(trace_result_at(t, 9), 0 - 1)
}

@[test]
fn test_identical_replay_is_equivalent() {
    // A deterministic replay reproduces the recorded trace exactly.
    let original = trace_record(trace_record(trace_new(), 1, 10), 2, 20)
    let replay = trace_record(trace_record(trace_new(), 1, 10), 2, 20)
    assert(trace_equiv(original, replay))
    assert_eq(trace_divergence(original, replay), 0 - 1)
}

@[test]
fn test_divergent_result_is_caught() {
    // Same actions, but step 1 produced a DIFFERENT result on replay (the
    // signature of non-determinism). Equiv fails; divergence points at step 1.
    let original = trace_record(trace_record(trace_new(), 1, 10), 2, 20)
    let replay = trace_record(trace_record(trace_new(), 1, 10), 2, 99)
    assert(!trace_equiv(original, replay))
    assert_eq(trace_divergence(original, replay), 1)
}

@[test]
fn test_divergent_action_is_caught() {
    // The replay took a DIFFERENT branch at step 0 (action 1 vs 7).
    let original = trace_record(trace_new(), 1, 10)
    let replay = trace_record(trace_new(), 7, 10)
    assert(!trace_equiv(original, replay))
    assert_eq(trace_divergence(original, replay), 0)
}

@[test]
fn test_length_mismatch_diverges_at_the_short_end() {
    // The replay ran one extra step — they agree on the common prefix, then
    // diverge at the point the shorter trace ended.
    let original = trace_record(trace_new(), 1, 10)
    let replay = trace_record(trace_record(trace_new(), 1, 10), 2, 20)
    assert(!trace_equiv(original, replay))
    assert_eq(trace_divergence(original, replay), 1)
}

@[test]
fn test_empty_traces_are_equivalent() {
    assert(trace_equiv(trace_new(), trace_new()))
    assert_eq(trace_divergence(trace_new(), trace_new()), 0 - 1)
}

fn main() {
    // Record a 3-step run, then replay it. A faithful (deterministic) replay is
    // equivalent; a replay where step 1 drifted is caught with the exact step.
    let recorded = trace_record(trace_record(trace_record(trace_new(), 1, 42), 2, 7), 3, 99)
    println("recorded {to_str(trace_len(recorded))} steps")

    let good_replay = trace_record(trace_record(trace_record(trace_new(), 1, 42), 2, 7), 3, 99)
    if trace_equiv(recorded, good_replay) {
        println("faithful replay: equivalent (deterministic) ✓")
    } else {
        println("faithful replay: DIVERGED at step {to_str(trace_divergence(recorded, good_replay))}")
    }

    // A replay where step 1's result drifted (e.g. an unseeded random crept in).
    let bad_replay = trace_record(trace_record(trace_record(trace_new(), 1, 42), 2, 13), 3, 99)
    let d = trace_divergence(recorded, bad_replay)
    if d < 0 {
        println("drifted replay: equivalent")
    } else {
        println("drifted replay: DIVERGED at step {to_str(d)} — non-determinism caught")
    }
}

sources.examples/asi/taint_flow.ax:
// taint_flow.ax
//
// AI Taint Flow Demo — information security for AI-generated values.
//
// Trust axis (integrity):
//   0=AI (untrusted)  1=Net  2=System  3=User  4=Constant
//
// Confidentiality axis:
//   0=Public  1=Internal  2=Confidential  3=Secret
//
// Rule 1: AI-sourced values (trust=0) cannot drive consequential actions
//         without human validation that elevates trust to the User floor (3).
//
// Rule 2: Secret data (level=3) cannot flow to AI sinks
//         (AI clearance = 0 = Public; the gap is 3 levels).
//
//   axon test examples/asi/taint_flow.ax
//   axon run  examples/asi/taint_flow.ax

// ── Trust level constants ─────────────────────────────────────────────────────
fn trust_ai()       -> i64 { 0 }
fn trust_net()      -> i64 { 1 }
fn trust_system()   -> i64 { 2 }
fn trust_user()     -> i64 { 3 }
fn trust_constant() -> i64 { 4 }

// ── Confidentiality level constants ──────────────────────────────────────────
fn cl_public()       -> i64 { 0 }
fn cl_internal()     -> i64 { 1 }
fn cl_confidential() -> i64 { 2 }
fn cl_secret()       -> i64 { 3 }

// ── Tainted: value + source trust level ──────────────────────────────────────
// Trust propagates pessimistically: combining two Tainted values yields the
// LOWER trust (taint is sticky). AI-sourced values start at trust=0.
type Tainted = { val: i64, trust: i64 }

fn tainted_ai(v: i64)   -> Tainted { Tainted { val: v, trust: trust_ai() } }
fn tainted_user(v: i64) -> Tainted { Tainted { val: v, trust: trust_user() } }

fn tainted_needs_validation(t: Tainted) -> bool {
    t.trust == trust_ai() || t.trust == trust_net()
}

// ── Trusted: a Tainted value that has passed an explicit validation gate ───────
// trust_validate succeeds only when t.trust >= floor; AI values (trust=0)
// always fail a trust_user() floor (3) unless the trust level is explicitly
// raised by a human approval step (see human_validate below).
type Trusted = { val: i64, trust: i64, floor: i64 }

fn trust_validate(t: Tainted, floor: i64) -> Result<Trusted, str> {
    if t.trust >= floor {
        Ok(Trusted { val: t.val, trust: t.trust, floor: floor })
    } else {
        Err("trust below validation floor")
    }
}

fn trusted_val(t: Trusted) -> i64 { t.val }

// ── Secret: value + confidentiality level ────────────────────────────────────
// A Secret at level L may only flow to a context whose clearance >= L.
// AI/Net sinks have clearance = cl_public() = 0, so they cannot read
// confidential or above — this is the exfiltration guard.
type Secret = { val: i64, level: i64 }

fn secret_can_flow_to(s: Secret, reader_clearance: i64) -> bool {
    reader_clearance >= s.level
}

fn secret_declassify(s: Secret, reader_clearance: i64) -> Result<i64, str> {
    if secret_can_flow_to(s, reader_clearance) {
        Ok(s.val)
    } else {
        Err("clearance insufficient for declassification")
    }
}

// ── Human validation gate ─────────────────────────────────────────────────────
// Simulates an explicit human reviewer approving an AI-generated value:
//   Step 1 — Bounds-check: reject values outside a safe operational range.
//   Step 2 — If safe: elevate trust to trust_user() (3) → Trusted.
// This two-step gate is the core of the demo: trust_validate alone cannot
// lift an AI value (trust=0) above the User floor without explicit human action.
fn human_validate(t: Tainted, reviewer: str) -> Result<Trusted, str> {
    if t.val < 0 || t.val > 1000000 {
        Err("rejected by {reviewer}: {to_str(t.val)} out of safe range [0, 1000000]")
    } else {
        Ok(Trusted { val: t.val, trust: trust_user(), floor: trust_user() })
    }
}

// ── Action gate: only Trusted values may drive consequential actions ───────────
fn execute_transfer(trusted: Trusted, account: str) -> Result<str, str> {
    Ok("transferred {to_str(trusted.val)} to {account} (trust={to_str(trusted.trust)}/4)")
}

// ── Tests ─────────────────────────────────────────────────────────────────────

@[test]
fn test_ai_output_is_untrusted() {
    let t = tainted_ai(500)
    assert_eq(t.trust, trust_ai())
}

@[test]
fn test_ai_value_blocked_by_trust_validate_alone() {
    // AI trust (0) cannot clear the User floor (3) without human elevation.
    let t = tainted_ai(500)
    match trust_validate(t, trust_user()) {
        Ok(_)  => assert(false)
        Err(_) => assert(true)
    }
}

@[test]
fn test_valid_ai_value_passes_human_validation() {
    let t = tainted_ai(500)
    match human_validate(t, "alice") {
        Ok(trusted) => assert_eq(trusted_val(trusted), 500)
        Err(_)      => assert(false)
    }
}

@[test]
fn test_human_validation_elevates_trust_to_user_level() {
    let t = tainted_ai(500)
    match human_validate(t, "alice") {
        Ok(trusted) => assert_eq(trusted.trust, trust_user())
        Err(_)      => assert(false)
    }
}

@[test]
fn test_out_of_range_ai_value_rejected() {
    let t = tainted_ai(-999999)
    match human_validate(t, "alice") {
        Ok(_)  => assert(false)
        Err(_) => assert(true)
    }
}

@[test]
fn test_secret_cannot_flow_to_ai() {
    let balance = Secret { val: 50000, level: cl_secret() }
    let ai_clearance = cl_public()
    assert(!secret_can_flow_to(balance, ai_clearance))
}

@[test]
fn test_secret_can_flow_to_authorized_context() {
    let balance = Secret { val: 50000, level: cl_confidential() }
    assert(secret_can_flow_to(balance, cl_confidential()))
    assert(secret_can_flow_to(balance, cl_secret()))
    assert(!secret_can_flow_to(balance, cl_public()))
}

@[test]
fn test_trusted_value_drives_action() {
    let t = tainted_ai(500)
    match human_validate(t, "alice") {
        Ok(trusted) => {
            match execute_transfer(trusted, "savings-account") {
                Ok(_)  => assert(true)
                Err(_) => assert(false)
            }
        }
        Err(_) => assert(false)
    }
}

@[test]
fn test_tainted_needs_validation_flags_ai_and_net() {
    assert(tainted_needs_validation(tainted_ai(1)))
    assert(!tainted_needs_validation(tainted_user(1)))
}

// ── main() — three-scenario narrative ────────────────────────────────────────

fn main() {
    println("=== AI Taint Flow Demo ===\n")

    // Scenario 1: Happy path — AI recommends a safe value, human approves.
    println("Scenario 1: Valid AI recommendation")
    let ai_rec = tainted_ai(500)
    println("  AI recommendation: {to_str(ai_rec.val)} (trust={to_str(ai_rec.trust)}/4)")
    if tainted_needs_validation(ai_rec) {
        println("  → flagged: needs human validation before action")
    }
    match human_validate(ai_rec, "alice") {
        Ok(trusted) => {
            println("  Human validated: trust raised to {to_str(trusted.trust)}/4 (User level)")
            match execute_transfer(trusted, "savings-account") {
                Ok(msg) => println("  SUCCESS: {msg}")
                Err(e)  => println("  ERROR: {e}")
            }
        }
        Err(e) => println("  BLOCKED: {e}")
    }

    // Scenario 2: Injection attempt — AI recommends an out-of-range value.
    println("\nScenario 2: Malicious AI recommendation (value injection)")
    let evil_rec = tainted_ai(-999999)
    println("  AI recommendation: {to_str(evil_rec.val)} (trust={to_str(evil_rec.trust)}/4)")
    match human_validate(evil_rec, "alice") {
        Ok(_)  => println("  ERROR: should have been rejected!")
        Err(e) => println("  BLOCKED: {e}")
    }

    // Scenario 3: Exfiltration attempt — confidential balance must not reach AI.
    println("\nScenario 3: Confidential data — exfiltration attempt blocked")
    let balance = Secret { val: 50000, level: cl_secret() }
    let ai_clearance = cl_public()
    println("  Account balance: classified at level {to_str(balance.level)}/3 (Secret)")
    println("  AI sink clearance:            {to_str(ai_clearance)}/3 (Public)")
    if secret_can_flow_to(balance, ai_clearance) {
        println("  ERROR: secret flowed to AI!")
    } else {
        println("  BLOCKED: balance (level={to_str(balance.level)}) cannot flow to AI (clearance={to_str(ai_clearance)})")
        println("  Safe: AI never sees the actual balance value")
    }
    // A root-level context (clearance = cl_secret = 3) can still declassify.
    match secret_declassify(balance, cl_secret()) {
        Ok(v)  => println("  Root context (clearance=3) declassified: {to_str(v)}")
        Err(_) => println("  (unexpected block)")
    }

    println("\n=== Taint Flow Demo Complete ===")
}

sources.examples/stdlib/constraint.ax:
// Tier-1 stdlib: Constraint — hard rules that must hold (vs soft scores).
//
// A goal's Score is a soft objective to maximize; a Constraint is a HARD rule
// whose violation disqualifies a candidate outright (score 0), regardless of
// how good it otherwise looks. Keeping the two separate is central to safe
// optimization — you never deploy a high-scoring candidate that breaks a
// must-hold rule.
//
//   axon test examples/stdlib/constraint.ax
//   axon run  examples/stdlib/constraint.ax

type Constraint = { name: str, satisfied: bool }

fn constraint(name: str, satisfied: bool) -> Constraint {
    Constraint { name: name, satisfied: satisfied }
}

// A range constraint: `value` must be within [lo, hi].
fn within(name: str, value: i64, lo: i64, hi: i64) -> Constraint {
    constraint(name, value >= lo && value <= hi)
}

// A ceiling constraint: `value` must be <= cap.
fn at_most(name: str, value: i64, cap: i64) -> Constraint {
    constraint(name, value <= cap)
}

// Disqualify (score 0) when violated, reporting which rule failed; else pass
// the score through unchanged.
fn enforce(c: Constraint, score: i64) -> i64 {
    if c.satisfied {
        score
    } else {
        let nm = c.name
        eprintln("constraint violated: {nm}")
        0
    }
}

// Both constraints must hold.
fn both(a: Constraint, b: Constraint) -> bool {
    a.satisfied && b.satisfied
}

@[test]
fn test_enforce_passthrough_when_ok() {
    assert_eq(enforce(constraint("c", true), 50), 50)
}

@[test]
fn test_enforce_disqualifies_when_violated() {
    assert_eq(enforce(constraint("c", false), 50), 0)
}

@[test]
fn test_within() {
    assert(within("len", 100, 0, 280).satisfied)
    assert(!within("len", 300, 0, 280).satisfied)
}

@[test]
fn test_at_most() {
    assert(at_most("tokens", 7000, 8000).satisfied)
    assert(!at_most("tokens", 9000, 8000).satisfied)
}

@[test]
fn test_both() {
    assert(both(constraint("a", true), constraint("b", true)))
    assert(!both(constraint("a", true), constraint("b", false)))
}

fn main() {
    // A candidate summary: quality 92, but it must also fit in 280 chars.
    let quality = 92
    let length = 305
    let fits = at_most("length<=280", length, 280)
    let final_score = enforce(fits, quality)
    println("quality {to_str(quality)}, length {to_str(length)} -> final score {to_str(final_score)}")
    if final_score == 0 {
        println("disqualified: a hard constraint was violated despite high quality")
    }
}

sources.examples/stdlib/principal.ax:
// Tier-1 stdlib: Principal — capability-based authorization for agents.
//
// An autonomous agent should only perform actions it is *permitted* to. A
// Principal carries a capability set (mirroring @[contained]'s net/fs/exec
// surface); `require_cap` gates an action's score on holding the capability,
// denying (score 0) and reporting otherwise. This is the permission counterpart
// to Budget (how much), Constraint (correctness), and Uncertain (how sure).
//
//   axon test examples/stdlib/principal.ax
//   axon run  examples/stdlib/principal.ax

type Principal = { name: str, net: bool, fs_write: bool, exec: bool }

// A principal with no capabilities — the safe default for an untrusted agent.
fn sandboxed(name: str) -> Principal {
    Principal { name: name, net: false, fs_write: false, exec: false }
}

fn principal(name: str, net: bool, fs_write: bool, exec: bool) -> Principal {
    Principal { name: name, net: net, fs_write: fs_write, exec: exec }
}

// Allow `score` only if the capability is granted; else deny (0) + report.
fn require_cap(granted: bool, cap: str, score: i64) -> i64 {
    if granted {
        score
    } else {
        let c = cap
        eprintln("capability denied: {c}")
        0
    }
}

@[test]
fn test_sandboxed_denies() {
    let p = sandboxed("agent")
    assert(!p.net)
    assert(!p.fs_write)
    assert(!p.exec)
    assert_eq(require_cap(p.net, "net", 50), 0)
}

@[test]
fn test_granted_allows() {
    let p = principal("agent", true, false, false)
    assert(p.net)
    assert_eq(require_cap(p.net, "net", 50), 50)
}

@[test]
fn test_principal_capabilities() {
    let p = principal("a", true, false, true)
    assert(p.net)
    assert(!p.fs_write)
    assert(p.exec)
}

fn main() {
    let agent = sandboxed("summarizer")
    let s1 = require_cap(agent.net, "net", 80)
    println("sandboxed agent, net action -> score {to_str(s1)} (denied)")

    let trusted = principal("trusted-fetcher", true, false, false)
    let s2 = require_cap(trusted.net, "net", 80)
    println("net-granted agent, net action -> score {to_str(s2)} (allowed)")

    let s3 = require_cap(trusted.exec, "exec", 80)
    println("net-granted agent, exec action -> score {to_str(s3)} (denied; no exec cap)")
}

sources.examples/stdlib/tainted.ax:
// Tier-2 stdlib: info-flow lattice — Tainted, Trusted, Secret, Public.
//
// ROADMAP §6 Tier-2 types: `Tainted<T>`, `Trusted<T>`, `Secret<T>`, `Public<T>`.
// These are VALUE TYPES that pair an i64 with an info-flow property, making the
// data-sensitivity and data-trust contracts OBSERVABLE and CHECKABLE in userland
// — the value-level counterpart to the kernel `@[contained]` / effect-row checks.
//
// Two orthogonal axes:
//
//   TRUST axis (who produced this data? how reliable is it?)
//   ─────────────────────────────────────────────────────────
//   Tainted  — wraps a value with a SOURCE TRUST LEVEL (0=AI .. 4=Constant).
//              Combining two Tainted values yields the LOWER trust (taint propagates).
//              Derived from source.ax's trust lattice.
//   Trusted  — a Tainted value that has been EXPLICITLY VALIDATED against a floor.
//              The validation is the explicit user approval the ROADMAP requires
//              before a low-trust value can drive a consequential action.
//
//   CONFIDENTIALITY axis (who may READ this data?)
//   ────────────────────────────────────────────────
//   Secret   — wraps a value with a CONFIDENTIALITY LEVEL (0=public .. 3=secret).
//              A Secret may only flow to a context whose CLEARANCE >= its level.
//   Public   — a value with no flow restrictions (shorthand for Secret at level 0).
//
// KEY CONTRACTS (the tests are the spec):
//   - `tainted_combine` propagates the LOWER of two trust levels (taint is sticky).
//   - `trust_validate` returns Err when the value's trust is below the floor.
//   - `secret_can_flow_to` is false when the reader's clearance < the secret's level.
//   - An AI-tainted value (trust=0) must clear a User-floor validation before it can
//     become Trusted and be used in a consequential path.
//
// Relationship to source.ax: source.ax tracks VALUE PROVENANCE (which source produced
// a scalar).  tainted.ax is FLOW TYPING: the value itself carries its constraints so
// the Axon type checker / effect system can reason about where it is allowed to go.
//
//   axon test examples/stdlib/tainted.ax
//   axon run  examples/stdlib/tainted.ax

// ── Trust constants (mirrors source.ax) ──────────────────────────────────────
fn trust_ai()       -> i64 { 0 }   // AI inference — can be confidently wrong
fn trust_net()      -> i64 { 1 }   // network response — could be adversarial
fn trust_system()   -> i64 { 2 }   // system sensor / runtime reading
fn trust_user()     -> i64 { 3 }   // human-stated intent
fn trust_constant() -> i64 { 4 }   // in-source-code constant — maximally trusted

// ── Confidentiality level constants ──────────────────────────────────────────
fn cl_public()       -> i64 { 0 }  // no restrictions; anyone may read
fn cl_internal()     -> i64 { 1 }  // internal use; not for external AI/Net
fn cl_confidential() -> i64 { 2 }  // confidential; requires elevated clearance
fn cl_secret()       -> i64 { 3 }  // secret; only root-level contexts may access

// ── Tainted ───────────────────────────────────────────────────────────────────
// A value paired with its SOURCE TRUST LEVEL. Trust propagates pessimistically:
// any derivation involving a low-trust value produces a low-trust result.

type Tainted = { val: i64, trust: i64 }

fn tainted(v: i64, trust: i64) -> Tainted {
    assert(trust >= 0 && trust <= 4)
    Tainted { val: v, trust: trust }
}

fn tainted_ai(v: i64)       -> Tainted { Tainted { val: v, trust: trust_ai() } }
fn tainted_net(v: i64)      -> Tainted { Tainted { val: v, trust: trust_net() } }
fn tainted_system(v: i64)   -> Tainted { Tainted { val: v, trust: trust_system() } }
fn tainted_user(v: i64)     -> Tainted { Tainted { val: v, trust: trust_user() } }
fn tainted_constant(v: i64) -> Tainted { Tainted { val: v, trust: trust_constant() } }

// Combine two Tainted values: the result takes the LOWER trust (taint is sticky).
// The combined value is the sum of the two vals (a placeholder — replace with
// the actual combining operation in real use).
fn tainted_combine(a: Tainted, b: Tainted) -> Tainted {
    let t = if a.trust <= b.trust { a.trust } else { b.trust }
    Tainted { val: a.val + b.val, trust: t }
}

// Apply a pure function to the Tainted value, preserving the trust tag.
fn tainted_map(t: Tainted, delta: i64) -> Tainted {
    Tainted { val: t.val + delta, trust: t.trust }
}

// Does this Tainted value need human/explicit validation before it drives an action?
fn tainted_needs_validation(t: Tainted) -> bool {
    t.trust == trust_ai() || t.trust == trust_net()
}

// ── Trusted ───────────────────────────────────────────────────────────────────
// A Tainted value that has passed an EXPLICIT VALIDATION gate (trust >= floor).
// This is the "human sign-off" / "explicit approval" the ROADMAP requires before
// a low-trust value can drive a consequential action (ROADMAP §2.4: the AST is
// the legal artifact, not the English).

type Trusted = { val: i64, trust: i64, floor: i64 }

// Validate: if t.trust >= floor, return Trusted(ok); else Err.
fn trust_validate(t: Tainted, floor: i64) -> Result<Trusted, str> {
    if t.trust >= floor {
        Ok(Trusted { val: t.val, trust: t.trust, floor: floor })
    } else {
        Err("trust below validation floor")
    }
}

// Extract the value from a Trusted value (no further checks needed — it has
// already passed the floor).
fn trusted_val(t: Trusted) -> i64 { t.val }
fn trusted_trust(t: Trusted) -> i64 { t.trust }

// Trusted values can be further combined; result is still Trusted if both parts
// cleared the SAME floor. Returns the lower-trust part.
fn trusted_combine(a: Trusted, b: Trusted) -> Trusted {
    let min_floor = if a.floor <= b.floor { a.floor } else { b.floor }
    let t = if a.trust <= b.trust { a.trust } else { b.trust }
    Trusted { val: a.val + b.val, trust: t, floor: min_floor }
}

// ── Secret ────────────────────────────────────────────────────────────────────
// A value with a CONFIDENTIALITY LEVEL. A Secret at level L may only flow to
// contexts whose clearance >= L. This enforces the "need to know" principle.
//
// The classic info-flow rule: SECRET data cannot flow DOWN to a PUBLIC sink
// (exfiltration). Exfiltration via AI/Net is the primary concern for ASI agents
// that process confidential data and then call out to external models.

type Secret = { val: i64, level: i64 }

fn secret(v: i64, level: i64) -> Secret {
    assert(level >= 0 && level <= 3)
    Secret { val: v, level: level }
}

fn secret_public(v: i64)       -> Secret { Secret { val: v, level: cl_public() } }
fn secret_internal(v: i64)     -> Secret { Secret { val: v, level: cl_internal() } }
fn secret_confidential(v: i64) -> Secret { Secret { val: v, level: cl_confidential() } }
fn secret_secret(v: i64)       -> Secret { Secret { val: v, level: cl_secret() } }

// Can this Secret flow to a reader/context with the given clearance?
// Rule: reader_clearance >= secret.level → allowed; else blocked.
fn secret_can_flow_to(s: Secret, reader_clearance: i64) -> bool {
    reader_clearance >= s.level
}

// Declassify: if reader has sufficient clearance, produce a Public value.
// Public means "no flow restrictions from this point on."
fn secret_declassify(s: Secret, reader_clearance: i64) -> Result<i64, str> {
    if secret_can_flow_to(s, reader_clearance) {
        Ok(s.val)
    } else {
        Err("clearance insufficient for declassification")
    }
}

// Join two secrets: result takes the HIGHER confidentiality level (more restrictive).
// Combining a public and a confidential piece produces a confidential result.
fn secret_combine(a: Secret, b: Secret) -> Secret {
    let level = if a.level >= b.level { a.level } else { b.level }
    Secret { val: a.val + b.val, level: level }
}

// ── Public ────────────────────────────────────────────────────────────────────
// A value with no flow restrictions — either it was never sensitive, or it has
// been explicitly declassified by an authorized context.
//
// Public is a zero-overhead tag: it marks that the value has cleared any flow
// check, so callers don't need to re-check. It composes cleanly with Tainted:
// a Public value may still have a low TRUST level (e.g., an AI inference that
// has been validated as non-sensitive).

type Public = { val: i64 }

fn public(v: i64) -> Public { Public { val: v } }
fn public_val(p: Public) -> i64 { p.val }

// Pair a Public value with a trust tag, producing a Tainted (so it can
// participate in the trust-propagation lattice).
fn public_with_trust(p: Public, trust: i64) -> Tainted {
    Tainted { val: p.val, trust: trust }
}

// ════════════════════════════════════════════════════════════════════════════
//  Tests — the info-flow contracts
// ════════════════════════════════════════════════════════════════════════════

// ── Tainted tests ─────────────────────────────────────────────────────────────

@[test]
fn test_taint_propagates_pessimistically() {
    // Constant + AI → AI (the least-trusted wins).
    let c = tainted_constant(100)
    let a = tainted_ai(50)
    let r = tainted_combine(c, a)
    assert_eq(r.trust, trust_ai())
}

@[test]
fn test_taint_combine_is_commutative_on_trust() {
    let a = tainted_user(10)
    let b = tainted_net(20)
    let ab = tainted_combine(a, b)
    let ba = tainted_combine(b, a)
    assert_eq(ab.trust, ba.trust)
}

@[test]
fn test_tainted_map_preserves_trust() {
    let t = tainted_net(42)
    let t2 = tainted_map(t, 8)
    assert_eq(t2.val, 50)
    assert_eq(t2.trust, trust_net())
}

@[test]
fn test_tainted_needs_validation_for_ai_and_net() {
    assert(tainted_needs_validation(tainted_ai(1)))
    assert(tainted_needs_validation(tainted_net(1)))
    assert(!tainted_needs_validation(tainted_user(1)))
    assert(!tainted_needs_validation(tainted_constant(1)))
}

// ── Trusted tests ─────────────────────────────────────────────────────────────

@[test]
fn test_trust_validate_succeeds_above_floor() {
    let t = tainted_user(99)
    let result = trust_validate(t, trust_user())
    match result {
        Ok(trusted) => assert_eq(trusted_val(trusted), 99)
        Err(_) => assert(false)
    }
}

@[test]
fn test_trust_validate_fails_below_floor() {
    // An AI-tainted value cannot clear a User-level floor.
    let t = tainted_ai(99)
    let result = trust_validate(t, trust_user())
    match result {
        Ok(_) => assert(false)
        Err(_) => assert(true)
    }
}

@[test]
fn test_ai_value_cannot_drive_consequential_action_without_validation() {
    // Simulate an AI-sourced score that must clear User-level trust before
    // it drives an action (the ROADMAP §2.4 / §5 "approval" gate).
    let ai_score = tainted_ai(85)

    // The "action" requires trust >= User:
    let validated = trust_validate(ai_score, trust_user())
    match validated {
        Ok(_) => assert(false)           // should NOT succeed
        Err(_) => assert(true)           // correctly blocked
    }

    // If the same score were from a user (explicit human approval):
    let user_score = tainted_user(85)
    let validated2 = trust_validate(user_score, trust_user())
    match validated2 {
        Ok(t) => assert_eq(trusted_val(t), 85)
        Err(_) => assert(false)
    }
}

// ── Secret / Public tests ──────────────────────────────────────────────────────

@[test]
fn test_secret_can_flow_to_sufficient_clearance() {
    let s = secret_confidential(42)           // level=2
    assert(secret_can_flow_to(s, cl_confidential()))  // clearance 2 = ok
    assert(secret_can_flow_to(s, cl_secret()))        // clearance 3 > 2 = ok
    assert(!secret_can_flow_to(s, cl_internal()))     // clearance 1 < 2 = blocked
    assert(!secret_can_flow_to(s, cl_public()))       // clearance 0 < 2 = blocked
}

@[test]
fn test_secret_cannot_exfiltrate_to_ai_clearance() {
    // An AI/Net context has clearance = cl_public (0) — it has no access to
    // confidential or above. This is the exfiltration guard.
    let confidential_data = secret_confidential(1234)
    let ai_clearance = cl_public()     // AI/Net contexts cannot read confidential data
    assert(!secret_can_flow_to(confidential_data, ai_clearance))
}

@[test]
fn test_declassify_allows_sufficient_clearance() {
    let s = secret_internal(77)
    let result = secret_declassify(s, cl_internal())
    match result {
        Ok(v) => assert_eq(v, 77)
        Err(_) => assert(false)
    }
}

@[test]
fn test_declassify_blocks_insufficient_clearance() {
    let s = secret_secret(77)
    let result = secret_declassify(s, cl_confidential())  // one level short
    match result {
        Ok(_) => assert(false)
        Err(_) => assert(true)
    }
}

@[test]
fn test_secret_combine_takes_max_level() {
    // Public + Confidential → Confidential (most restrictive).
    let a = secret_public(10)
    let b = secret_confidential(20)
    let r = secret_combine(a, b)
    assert_eq(r.level, cl_confidential())
}

@[test]
fn test_public_is_freely_shareable() {
    let p = public(42)
    let s = secret_public(p.val)
    assert(secret_can_flow_to(s, cl_public()))
    assert(secret_can_flow_to(s, cl_secret()))   // all clearances ≥ 0
}

// ── Headline: the full info-flow pipeline ────────────────────────────────────
// An AI agent receives a CONFIDENTIAL input, processes it, and tries to send
// the result to an external endpoint (AI/Net clearance = 0 = public).
// The Secret type blocks this exfiltration attempt.
@[test]
fn test_no_exfiltration_of_confidential_to_ai() {
    let confidential_input = secret_confidential(9999)  // level=2

    // Agent processes the input (operation on raw val — in production, the
    // agent would receive a Trusted value, not a raw int, but this demo
    // shows the flow check at the SINK):
    let processed = secret(confidential_input.val * 2, cl_confidential())

    // Sink is an AI/Net call with clearance = cl_public (0).
    let ai_net_clearance = cl_public()
    let can_send = secret_can_flow_to(processed, ai_net_clearance)
    assert(!can_send)   // BLOCKED: confidential data may not flow to AI/Net

    // A Public result CAN be sent to the AI/Net sink:
    let public_result = secret_public(42)
    assert(secret_can_flow_to(public_result, ai_net_clearance))
}

fn main() -> i64 {
    println("── tainted: trust (integrity) axis ────────────────────────────")
    let ai_score = tainted_ai(85)
    println("AI-sourced score: {to_str(ai_score.val)} (trust={to_str(ai_score.trust)}/4)")
    if tainted_needs_validation(ai_score) {
        println("→ needs validation before driving a consequential action")
    }
    let validated = trust_validate(ai_score, trust_user())
    match validated {
        Ok(_) => println("→ validation passed (unexpected)")
        Err(e) => println("→ validation blocked: {e}")
    }
    let user_score = tainted_user(85)
    let v2 = trust_validate(user_score, trust_user())
    match v2 {
        Ok(t) => println("→ user-sourced score {to_str(trusted_val(t))} cleared the User floor")
        Err(_) => println("→ unexpected failure")
    }
    println("")
    println("── tainted: confidentiality (secrecy) axis ─────────────────────")
    let conf = secret_confidential(1234)
    let ai_clearance = cl_public()
    if !secret_can_flow_to(conf, ai_clearance) {
        println("→ BLOCKED: confidential data (level 2) cannot flow to AI/Net (clearance 0)")
    }
    let result = secret_declassify(conf, cl_secret())
    match result {
        Ok(v) => println("→ root-level principal (clearance 3) declassified value: {to_str(v)}")
        Err(_) => println("→ unexpected block")
    }
    0
}

